import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        Map<String, Integer> cost = Map.of("unit", 1, "component", 5, "e2e", 20);
        int budget = s.nextInt(), n = s.nextInt(), estimate = 0;
        for (int i = 0; i < n; i++) estimate += cost.get(s.next());
        List<String> gates = List.of("compile", "test", "scan", "package");
        System.out.println("ESTIMATE " + estimate);
        boolean within = estimate <= budget;
        System.out.println(within ? "WITHIN_BUDGET " + (budget - estimate) : "OVER_BUDGET " + (estimate - budget));
        boolean allPass = true;
        for (String gate : gates) if (s.nextInt() == 0) {
            System.out.println("FAILED " + gate);
            allPass = false;
        }
        System.out.println(allPass && within ? "RELEASE" : "BLOCK");
    }
}
